--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `ID` bigint NOT NULL AUTO_INCREMENT,
  `USER_ID` bigint NOT NULL,
  `USER_PROMOTION_ID` bigint DEFAULT NULL,
  `RECEIVER_NAME` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `RECEIVER_PHONE` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `SHIPPING_ADDRESS` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `TOTAL_AMOUNT` decimal(12,2) NOT NULL,
  `DISCOUNT_AMOUNT` decimal(12,2) DEFAULT '0.00',
  `FINAL_AMOUNT` decimal(12,2) NOT NULL,
  `ORDER_STATUS` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `PAYMENT_STATUS` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `PAYMENT_METHOD` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `NOTE` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `VERSION` bigint NOT NULL DEFAULT '0',
  `CREATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATED_AT` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `USER_PROMOTION_ID` (`USER_PROMOTION_ID`),
  KEY `FK_ORDERS_USERS` (`USER_ID`),
  CONSTRAINT `FK_ORDERS_USER_PROMOTION` FOREIGN KEY (`USER_PROMOTION_ID`) REFERENCES `user_promotion` (`ID`),
  CONSTRAINT `FK_ORDERS_USERS` FOREIGN KEY (`USER_ID`) REFERENCES `users` (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

