INSERT INTO `settings` VALUES (1,'SHIPPING_FEE','1000','Phí giao hàng cố định (VND)','2026-08-05 02:11:25','2026-08-05 02:32:16',0),(2,'FREE_SHIPPING_THRESHOLD','20000000','Đơn trên mức này được miễn phí giao hàng (VND)','2026-08-05 02:11:25','2026-08-06 07:39:25',0),(3,'TERMS_CONDITIONS','<h2>Điều khoản sử dụng</h2><p>Chào mừng bạn đến với GreenPhone. Khi truy cập và sử dụng website, bạn đồng ý với các điều khoản sau:</p><h3>1. Tài khoản</h3><p>Bạn phải cung cấp thông tin chính xác khi đăng ký tài khoản và chịu trách nhiệm bảo mật mật khẩu của mình.</p><h3>2. Đặt hàng &amp; thanh toán</h3><p>Mọi đơn hàng phải được thanh toán đầy đủ trước khi giao hàng. Giá và khuyến mãi có thể thay đổi mà không cần báo trước.</p><h3>3. Bảo hành &amp; đổi trả</h3><p>Sản phẩm được bảo hành 12 tháng theo chính sách của nhà sản xuất. Đổi trả trong 30 ngày nếu lỗi nhà sản xuất.</p><h3>4. Trách nhiệm pháp lý</h3><p>GreenPhone không chịu trách nhiệm cho các thiệt hại phát sinh từ việc sử dụng sai mục đích thông tin trên website.</p>','Điều khoản sử dụng (HTML)','2026-08-05 10:21:17','2026-08-05 10:30:01',0),(4,'PRIVACY_POLICY','<h2><strong>Chính sách bảo mật</strong></h2><p>GreenPhone cam kết bảo vệ thông tin cá nhân của khách hàng. Chính sách này mô tả cách chúng tôi thu thập và sử dụng dữ liệu.</p><p></p><p><strong>1. Thông tin chúng tôi thu thập</strong></p><p>Họ tên, email, số điện thoại, địa chỉ giao hàng và lịch sử mua hàng.</p><p></p><p><strong>2. Mục đích sử dụng</strong></p><p>Xử lý đơn hàng, giao hàng, hỗ trợ khách hàng và gửi thông báo khuyến mãi (khi bạn đồng ý).</p><p></p><p><strong>3. Chia sẻ thông tin</strong></p><p>Chúng tôi không bán thông tin cho bên thứ ba. Thông tin chỉ chia sẻ cho đối tác vận chuyển để giao hàng.</p><p></p><p><strong>4. Bảo mật dữ liệu</strong></p><p>Thông tin được mã hóa và bảo vệ bằng các biện pháp kỹ thuật phù hợp.</p><p></p><p><strong>5. Quyền của bạn</strong></p><p>Bạn có quyền truy cập, chỉnh sửa hoặc yêu cầu xóa thông tin cá nhân bất kỳ lúc nào qua email hỗ trợ.</p><p></p>','Chính sách bảo mật (HTML)','2026-08-05 10:21:17','2026-08-05 10:30:01',0);
/*!40000 ALTER TABLE `settings` ENABLE KEYS */;
